try {
  const body = $input.first().json.body || $input.first().json;
  const toolCallList = body?.message?.toolCallList || [];
  if (toolCallList.length === 0) throw new Error('empty toolCallList');
  const toolCall = toolCallList[0];
  const toolCallId = toolCall.id || 'unknown';
  let args = {};
  try { args = typeof toolCall.function?.arguments === 'string' ? JSON.parse(toolCall.function.arguments) : (toolCall.function?.arguments || {}); } catch(e) { args = {}; }
  const patientName = (args.patientName || '').trim();
  const phone = (args.phone || args.patientPhone || '').trim();
  const doctorName = (args.doctorName || '').trim();
  const appointmentDate = (args.appointmentDate || '').trim();
  const appointmentTime = (args.appointmentTime || '').trim();
  const notes = (args.notes || '').trim();
  if (!patientName || !phone || !doctorName || !appointmentDate || !appointmentTime) {
    return [{ json: { toolCallId, error: true, result: 'Randevu oluşturmak için hasta adı, telefon, doktor adı, tarih ve saat bilgisi gereklidir.' } }];
  }
  return [{ json: { toolCallId, patientName, phone, doctorName, appointmentDate, appointmentTime, notes, error: false } }];
} catch(e) {
  return [{ json: { toolCallId: 'unknown', error: true, result: 'İsteğinizi işlerken bir hata oluştu. Lütfen tekrar deneyin.' } }];
}
